<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{postForm}from'../../lib/api';import{listOntAcs,listOntDiscovery,listOntInventory}from'./api';import type{OntRow}from'./contracts';type Tab='inventory'|'discovery'|'acs';const tab=ref<Tab>('inventory'),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),inventory=ref<OntRow[]>([]),discovery=ref<OntRow[]>([]),acs=ref<OntRow[]>([]),detailOpen=ref(false),formOpen=ref(false),selected=ref<OntRow|null>(null),editing=ref<OntRow|null>(null),ontForm=ref({serial_number:'',vendor:'',model:'',status:'UNASSIGNED'});const rows=computed(()=>tab.value==='inventory'?inventory.value:tab.value==='discovery'?discovery.value:acs.value);const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return rows.value.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));});function tone(v?:string):'success'|'danger'|'warning'|'neutral'{const s=String(v||'').toUpperCase();return['ASSIGNED','KNOWN','MATCHED','ONLINE'].includes(s)?'success':['OFFLINE','ROGUE','UNMATCHED'].includes(s)?'danger':['STALE','UNASSIGNED'].includes(s)?'warning':'neutral';}function status(row:OntRow){return tab.value==='inventory'?row.status:tab.value==='discovery'?row.inventory_state:row.acs_status||(row.inventory_id?'MATCHED':'UNMATCHED');}function fmt(v?:string){return v?new Date(v.replace(' ','T')).toLocaleString():'—';}function uptime(s?:number){if(!s)return'—';const d=Math.floor(s/86400),h=Math.floor((s%86400)/3600),m=Math.floor((s%3600)/60);return`${d}d ${h}h ${m}m`;}async function load(showNotice=false){loading.value=true;error.value='';notice.value='';try{const[i,d,a]=await Promise.all([listOntInventory(),listOntDiscovery(),listOntAcs()]);inventory.value=i||[];discovery.value=d||[];acs.value=a||[];if(showNotice)notice.value='ONT datasets refreshed.';}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to load ONT devices.';}finally{loading.value=false;}}function show(row:OntRow){selected.value=row;detailOpen.value=true;}function openOnt(row?:OntRow){editing.value=row||null;ontForm.value={serial_number:String(row?.serial_number||''),vendor:String(row?.vendor||''),model:String(row?.model||''),status:String(row?.status||'UNASSIGNED')};formOpen.value=true;}async function submitOnt(){saving.value=true;error.value='';try{const fd=new FormData();Object.entries(ontForm.value).forEach(([k,v])=>fd.set(k,v));fd.set('subscriber_id',String(editing.value?.subscriber_id||''));await postForm(editing.value?`/api/v1/ont-devices/update/${editing.value.id}`:'/api/v1/ont-devices/store',fd);formOpen.value=false;notice.value=editing.value?'ONT updated.':'ONT added to inventory.';await load();}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to save ONT.';}finally{saving.value=false;}}async function addDiscovered(row:OntRow){if(!confirm(`Add ${row.serial_number||'this ONT'} to inventory?`))return;saving.value=true;try{const fd=new FormData();['serial_number','vendor','model','frame','slot','port'].forEach(k=>fd.set(k,String(row[k]??'')));await postForm('/api/v1/ont-devices/add-to-inventory',fd);notice.value='Discovered ONT added to inventory.';await load();}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to add ONT.';}finally{saving.value=false;}}async function discover(){if(!confirm('Run OLT auto discovery now?'))return;saving.value=true;try{await postForm('/api/v1/ont-devices/discover',new FormData());notice.value='ONT discovery completed.';await load();}catch(reason){error.value=reason instanceof Error?reason.message:'Discovery failed.';}finally{saving.value=false;}}onMounted(()=>void load());
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Access device inventory and ACS operations" title="ONT Devices" description="Review inventory, run OLT Auto Find, and manage ACS visibility in one workspace."><template #actions><NxButton variant="secondary" :disabled="loading||saving" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton variant="secondary" :disabled="saving" @click="discover">{{saving?'Working…':'Auto Find ONTs'}}</NxButton><NxButton :disabled="saving" @click="openOnt()">Add ONT</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="item in [['Inventory',inventory.length,'Tracked ONTs'],['Assigned',inventory.filter(r=>r.status==='ASSIGNED').length,'Linked to subscribers'],['Discovered',discovery.length,'OLT autofind records'],['ACS Devices',acs.length,'Remote-management visibility']]" :key="String(item[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0]}}</p><p class="mt-2 text-2xl font-bold">{{item[1]}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{item[2]}}</p></NxCard></section><NxToolbar><div class="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div role="tablist" aria-label="ONT views" class="flex flex-wrap gap-2"><button v-for="item in [['inventory','Inventory'],['discovery','Discovery'],['acs','Remote Management']]" :key="item[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="tab===item[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab=item[0] as Tab">{{item[1]}}</button></div><div class="flex w-full flex-col gap-2 sm:flex-row lg:w-auto"><NxButton v-if="tab==='discovery'" variant="secondary" :disabled="saving" @click="discover">Auto Find</NxButton><input v-model="search" type="search" placeholder="Search serial, model, subscriber…" class="min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface-muted)] px-4 lg:w-80"></div></div></NxToolbar>
<NxTableShell v-if="tab==='inventory'" min-width="920px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Serial</th><th class="px-4 py-3">Vendor / Model</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Created</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="6" class="px-4 py-12 text-center">No inventory records found.</td></tr><tr v-for="row in filtered" :key="row.id"><td class="px-4 py-3 font-mono font-bold">{{row.serial_number||'—'}}</td><td class="px-4 py-3"><p>{{row.vendor||'—'}}</p><p class="text-xs text-[var(--nx-text-muted)]">{{row.model||'Unknown model'}}</p></td><td class="px-4 py-3">{{row.subscriber_name||'Unassigned'}}</td><td class="px-4 py-3"><NxBadge :tone="tone(status(row))">{{status(row)||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3">{{fmt(row.created_at)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="show(row)">View</NxButton><NxButton variant="secondary" @click="openOnt(row)">Edit</NxButton></div></td></tr></tbody></NxTableShell>
<NxTableShell v-else-if="tab==='discovery'" min-width="980px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Serial</th><th class="px-4 py-3">Vendor / Model</th><th class="px-4 py-3">F/S/P</th><th class="px-4 py-3">Last Seen</th><th class="px-4 py-3">Inventory</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="6" class="px-4 py-12 text-center">No discovery records found. Use Auto Find to scan the configured OLT.</td></tr><tr v-for="row in filtered" :key="String(row.id)+row.serial_number"><td class="px-4 py-3 font-mono font-bold">{{row.serial_number||'—'}}</td><td class="px-4 py-3">{{row.vendor||'—'}} / {{row.model||'—'}}</td><td class="px-4 py-3 font-mono">{{row.fsp||`${row.frame??0}/${row.slot??0}/${row.port??0}`}}</td><td class="px-4 py-3">{{fmt(row.last_seen||row.autofind_time)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(status(row))">{{status(row)||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="show(row)">View</NxButton><NxButton v-if="String(row.inventory_state||'').toUpperCase()!=='KNOWN'" :disabled="saving" @click="addDiscovered(row)">Add to Inventory</NxButton></div></td></tr></tbody></NxTableShell>
<NxTableShell v-else min-width="1100px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Serial</th><th class="px-4 py-3">Vendor / Model</th><th class="px-4 py-3">WAN IP</th><th class="px-4 py-3">Last Seen</th><th class="px-4 py-3">Uptime</th><th class="px-4 py-3">ACS</th><th class="px-4 py-3">Inventory</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="8" class="px-4 py-12 text-center">No ACS devices found.</td></tr><tr v-for="row in filtered" :key="row.id"><td class="px-4 py-3 font-mono font-bold">{{row.serial_number||'—'}}</td><td class="px-4 py-3">{{row.vendor||'—'}} / {{row.model||'—'}}</td><td class="px-4 py-3 font-mono">{{row.wan_ip||'—'}}</td><td class="px-4 py-3">{{fmt(row.last_seen)}}</td><td class="px-4 py-3">{{uptime(row.uptime_seconds)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(row.acs_status)">{{row.acs_status||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(row.inventory_id?'MATCHED':'UNMATCHED')">{{row.inventory_id?'MATCHED':'UNMATCHED'}}</NxBadge></td><td class="px-4 py-3 text-right"><a :href="`/ont-devices/acs-device/${encodeURIComponent(String(row.id))}`" class="inline-flex min-h-10 items-center rounded-md bg-brand-600 px-4 text-sm font-semibold text-white no-underline">Open ACS Page</a></td></tr></tbody></NxTableShell>
<NxModal :open="formOpen" :title="editing?'Edit ONT':'Add ONT'" description="Maintain the ONT inventory record directly from this page." max-width="42rem" @close="formOpen=false"><form id="ont-current-form" class="grid gap-4 p-6 md:grid-cols-2" @submit.prevent="submitOnt"><label class="grid gap-2 text-sm font-semibold">Serial Number<input v-model.trim="ontForm.serial_number" required class="min-h-11 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 font-mono text-[var(--nx-text)]"></label><label class="grid gap-2 text-sm font-semibold">Status<select v-model="ontForm.status" class="min-h-11 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-[var(--nx-text)]"><option>UNASSIGNED</option><option>ASSIGNED</option><option>OFFLINE</option></select></label><label class="grid gap-2 text-sm font-semibold">Vendor<input v-model.trim="ontForm.vendor" class="min-h-11 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-[var(--nx-text)]"></label><label class="grid gap-2 text-sm font-semibold">Model<input v-model.trim="ontForm.model" class="min-h-11 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-[var(--nx-text)]"></label></form><template #footer><NxButton variant="secondary" :disabled="saving" @click="formOpen=false">Cancel</NxButton><NxButton type="submit" form="ont-current-form" :disabled="saving">{{saving?'Saving…':'Save ONT'}}</NxButton></template></NxModal><NxModal :open="detailOpen" title="ONT Details" :description="selected?.serial_number||'Inventory record'" max-width="56rem" @close="detailOpen=false"><dl class="grid gap-4 p-6 md:grid-cols-2"><div v-for="item in Object.entries(selected||{})" :key="item[0]"><dt class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0].replaceAll('_',' ')}}</dt><dd class="mt-1 break-all">{{item[1]??'—'}}</dd></div></dl><template #footer><NxButton @click="detailOpen=false">Close</NxButton></template></NxModal></div></template>
